import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"越调·天净沙马谦斋园亭","description":"","frontmatter":{"title":"越调·天净沙马谦斋园亭","date":"2026-11-11T00:00:00.000Z","seq":35,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/越调·天净沙马谦斋园亭.md","filePath":"blogs/元曲·张可久/越调·天净沙马谦斋园亭.md"}'),o={name:"blogs/元曲·张可久/越调·天净沙马谦斋园亭.md"};function c(l,a,n,_,m,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="越调·天净沙马谦斋园亭" tabindex="-1">越调·天净沙马谦斋园亭 <a class="header-anchor" href="#越调·天净沙马谦斋园亭" aria-label="Permalink to &quot;越调·天净沙马谦斋园亭&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">簪缨席上团栾，杖藜松下盘桓，喷玉西风脆管。</p><p class="poem-stanza">雪芳亭畔，秋香一树金丸。</p><p class="poem-stanza">雪中酬王一山瑶园树老琼枝，玉奴酒捧金卮，十二阑干倚徙。</p><p class="poem-stanza">探梅人至，灞桥诗等多时。</p><p class="poem-stanza">春情一言半语恩情，三番两次丁宁，万劫千生誓盟。</p><p class="poem-stanza">柳衰花病，春风何处莺莺？明月楼上有赠意中千里婵娟，楼头几度团圆？灯下些儿空便。</p><p class="poem-stanza">柳惊花颤，何时长在樽前？由德清道院来杭丹炉好养朱砂，洞门长掩青霞，又上西湖去马。</p><p class="poem-stanza">放心不下，桃源亭上梅花。</p><p class="poem-stanza">寒夜书事月移影落冰池，烟消香护帘长，枕上佳人未知，雪篝重被，小梅招得春归。</p><p class="poem-stanza">桃源洞苍云朵朵奇峰，翠蓬隐隐仙宫，醉眼帘花几重？小桃溪洞，刘郎不信秋风。</p><p class="poem-stanza">春晚翠帘不卷钩闲，华堂长见门关，血指频将泪弹。</p><p class="poem-stanza">玉人愁惯，杏花楼上春残。</p><p class="poem-stanza">秋感翠萍波底游鱼，碧悟井上啼乌，独立西风院宇。</p><p class="poem-stanza">相思何处？芭蕉一卷愁书。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
